import { collectFiles, fingerprint, fingerprintOf, createFingerprintIndex, cacheFile } from "@govlab/content-fingerprint";
import { existsSync } from "node:fs";

const index = createFingerprintIndex({ file: cacheFile("module-docs"), force: process.env.GOVLAB_NO_CACHE === "1" });
const shared = fingerprint([canonicalIndexPath, allRulesPath, govlabConfigPath]);
for (const unit of units) {
    const own = fingerprint([...collectFiles(unit.dir, { include: (n) => n.endsWith(".ts") }), unit.manifest]);
    const key = fingerprintOf([own, shared, GENERATOR_SOURCE]);
    if (index.unchanged(unit.id, key) && existsSync(unit.output)) { continue; }
    render(unit);
    index.update(unit.id, key);
}
index.flush();
